<section class="table-panel"><h3>Missions, avances et soldes</h3><table class="enterprise-table"><thead><tr><th>OM</th><th>Actif / responsable</th><th>Planning</th><th>Avances / justifié</th><th>Statut / action</th></tr></thead><tbody><?php foreach($data['missions'] as$m):?><tr><td><?=e($m['mission_number'].' — '.$m['purpose'])?></td><td><?=e($m['asset_code'].' / '.$m['person_name'])?></td><td><?=e($m['planned_start'].' → '.$m['planned_end'])?></td><td><?=e($m['advances'].' / '.$m['justified'])?></td><td><?=e($m['status'])?><?php if($m['status']==='submitted'):?><form method="post" action="<?=e(base_url('fuel-logistics/missions/'.$m['id'].'/approve'))?>"><?=csrf_field()?><button>Valider</button></form><?php elseif($m['status']==='approved'):?><form method="post" action="<?=e(base_url('fuel-logistics/missions/'.$m['id'].'/start'))?>"><?=csrf_field()?><input type="datetime-local" name="at"><input type="number" step="0.01" name="meter"><button>Démarrer</button></form><?php elseif($m['status']==='in_progress'):?><form method="post" action="<?=e(base_url('fuel-logistics/missions/'.$m['id'].'/complete'))?>"><?=csrf_field()?><input type="datetime-local" name="at"><input type="number" step="0.01" name="meter"><button>Terminer</button></form><?php elseif($m['status']==='justification_pending'):?><form method="post" action="<?=e(base_url('fuel-logistics/missions/'.$m['id'].'/settle'))?>"><?=csrf_field()?><button>Solder</button></form><?php endif;?><form method="post" action="<?=e(base_url('fuel-logistics/missions/'.$m['id'].'/advances'))?>"><?=csrf_field()?><input type="number" step="0.01" name="amount" placeholder="Avance"><button>Verser</button></form></td></tr><?php endforeach;?></tbody></table></section>
<div class="dashboard-grid dashboard-grid-2"><section class="form-panel"><h3>Justificatif d’avance</h3><form method="post" action="<?=e(base_url('fuel-logistics/justifications'))?>" class="enterprise-form"><?=csrf_field()?><input type="number" name="advance_id" placeholder="ID avance" required><select name="expense_type"><option value="fuel">Carburant</option><option value="toll">Péage</option><option value="lodging">Logement</option><option value="food">Restauration</option><option value="repair">Réparation</option><option value="other">Autre</option></select><input name="proof_reference" placeholder="Référence justificatif unique" required><input type="number" step="0.01" name="amount" placeholder="Montant"><input type="datetime-local" name="expense_at"><button>Justifier</button></form></section><section class="form-panel"><h3>Reliquat ou complément</h3><form method="post" action="<?=e(base_url('fuel-logistics/adjustments'))?>" class="enterprise-form"><?=csrf_field()?><input type="number" name="advance_id" placeholder="ID avance"><select name="adjustment_type"><option value="refund">Reliquat remboursé</option><option value="complement">Complément accordé</option></select><input type="number" step="0.01" name="amount" placeholder="Montant"><input name="reference" placeholder="Référence unique"><input type="datetime-local" name="adjusted_at"><button>Régulariser</button></form></section></div>
<section class="table-panel"><h3>KPIs de consommation</h3><table class="enterprise-table"><thead><tr><th>Actif</th><th>Réelle</th><th>Normative</th><th>Écart</th><th>Coût/km ou heure</th><th>Anomalies</th></tr></thead><tbody><?php foreach($data['kpis']['consumption'] as$k):?><tr><td><?=e($k['asset_code'])?></td><td><?=e(number_format($k['actual'],3,',',' '))?> L</td><td><?=e(number_format($k['normative'],3,',',' '))?> L</td><td><?=e(number_format($k['actual']-$k['normative'],3,',',' '))?> L</td><td><?=e($k['activity']>0?number_format($k['cost']/$k['activity'],2,',',' '):'—')?></td><td><?=e($k['anomalies'])?></td></tr><?php endforeach;?></tbody></table><h4>Péages par trajet</h4><?php foreach($data['kpis']['tolls'] as$k):?><p><?=e($k['route_code'].' : '.number_format($k['total'],2,',',' ').' / '.$k['passages'].' passage(s)')?></p><?php endforeach;?></section>
